// New Byzantium made ready for its first build (PLAN.md Phase 3, "Decisions taken (2026-11-01)"): the walk to a
// public connector (every place within 20 cells, the p90 from public floor within 14), the Mese alone widened to
// 8 cells with porticoes, the rock term of the budget (carved rock per tile from heights on the half-storey grid,
// outlines and seams; the structural and rock targets; the Core's figure), and the seam portals regenerated by
// levels/tools/city-portals.mjs; the gated upper city (every public way up under a checkpoint), the uncalibrated
// leaf estimate, placement on the plan (districts, ways, doors, ways over ways) and stairs at the rulebook's pitch.
// Each check passes on the spec and fails a copy broken in one way, by its sentence.
import { join } from "node:path";
import { readFileSync, writeFileSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { test, sure, HERE, tmp } from "./helper.mjs";
import { validateCity, CONNECTOR_TYPES } from "../levels/lib/city-description.mjs";
import { checkCity, analyseCity, cityPortals, diffPortals, ESTIMATE } from "../levels/lib/city-checks.mjs";
import { splicePortals } from "../levels/tools/city-portals.mjs";

const SPEC = join(HERE, "../levels/specs/newbyzantium.json");
const CHECK = join(HERE, "../levels/tools/check-city.mjs");
const PORTALS = join(HERE, "../levels/tools/city-portals.mjs");
const TEXT = readFileSync(SPEC, "utf8");
const fresh = () => JSON.parse(TEXT);
const byId = (list, id) => list.find((x) => x.id === id);
/** A copy changed by `change`, which must fail with a sentence containing every one of `words`. */
const breaks = (what, change, ...words) => {
  const d = fresh();
  change(d);
  const f = checkCity(d).failures.join(" | ");
  for (const w of words) sure(f.includes(w), `${what}: wanted a failure with "${w}", got: ${f || "PASS"}`);
};
/** Connectors taken out, and out of every checkpoint's `controls` (a checkpoint left with none goes too). */
const dropConnectors = (d, ids) => {
  d.connectors = d.connectors.filter((c) => !ids.includes(c.id));
  for (const k of d.checkpoints) k.controls = k.controls.filter((c) => !ids.includes(c));
  d.checkpoints = d.checkpoints.filter((k) => k.controls.length);
};

test("city prep: the walk to a connector, every place within 20 cells and the p90 from public floor within 14", () => {
  const d = fresh();
  sure(d.rules.connectors.maxWalk === 20 && d.rules.connectors.p90Walk === 14, JSON.stringify(d.rules.connectors));
  const r = checkCity(d);
  sure(r.pass, r.failures.join(" | "));
  const a = r.analysis;
  sure(a.walkP90Cells > 0 && a.walkP90Cells <= 14 && a.metrics.walkP90Cells === a.walkP90Cells, `p90 ${a.walkP90Cells}`);
  sure(a.walk.every((w) => w.distance <= 20 && w.p90 > 0), JSON.stringify(a.walk));
  // the Hollow and Palace Row, ~30 cells before, are served by their new stairs
  const hollow = byId(d.connectors, "c21_hollow_stair");
  const palace = byId(d.connectors, "c32_palace_stair");
  sure(hollow?.stops.includes("n1_hollow") && palace?.stops.includes("n3_palace"), "the Hollow's and Palace Row's stairs");
  breaks("the Hollow without its stair", (d) => dropConnectors(d, ["c21_hollow_stair", "c21_hollow_ladder"]), "on L1 the walk to a public connector is over 20 cells from n1_hollow"); // prettier-ignore
  breaks("Palace Row without its stairs", (d) => dropConnectors(d, ["c32_palace_stair", "c32_arcade_stair"]), "on L3 the walk to a public connector is over 20 cells from n3_palace"); // prettier-ignore
  breaks("the canal with no stair along it", (d) => dropConnectors(d, ["c21_pump_stair", "c21_basin_stair", "c21_shaft_gate"]), "the p90 walk from public floor to the nearest public connector is", "at most 14", "s1_canal_m"); // prettier-ignore
  breaks("a tighter p90", (d) => (d.rules.connectors.p90Walk = 10), `the p90 walk from public floor to the nearest public connector is ${a.walkP90Cells} cells, at most 10`); // prettier-ignore
  // a plaza's floor under a building is not floor; the measure is the city's, pooled over the layers
  const forum = fresh();
  byId(forum.buildings, "msr_nexus").footprint = [6, 6];
  byId(forum.buildings, "msr_nexus").tower.across = 5; // its tower on it
  sure(analyseCity(forum).walkP90Cells >= a.walkP90Cells, "more open forum floor walks no shorter");
});

test("city prep: the Mese alone widens to 8 cells with porticoes", () => {
  const d = fresh();
  const mese = d.streets.segments.filter((s) => s.name === "The Mese");
  sure(mese.length >= 3 && mese.every((s) => s.width === 8 && s.portico >= 1.5), JSON.stringify(mese.map((s) => [s.id, s.width, s.portico]))); // prettier-ignore
  sure(validateCity(d).errors.length === 0 && checkCity(d).pass, "the spec passes with its Mese");
  breaks("the Mese narrowed", (d) => (byId(d.streets.segments, "s3_north").width = 6), "space: s3_north (The Mese) is 6 cells wide, wanted 8"); // prettier-ignore
  breaks("the Mese without porticoes", (d) => delete byId(d.streets.segments, "s3_ministry").portico, "space: s3_ministry (The Mese) has no porticoes, wanted 1.5 each side"); // prettier-ignore
  breaks("another avenue widened", (d) => (byId(d.streets.segments, "s2_av_s").width = 8), "space: s2_av_s is 8 cells wide, over its class's 6: The Mese alone is widened"); // prettier-ignore
  breaks("no Mese at all", (d) => d.streets.segments.forEach((s) => delete s.name), "space: no way is named The Mese");
  // a portico is part of the width, beside the carriageway
  breaks("porticoes eating the road", (d) => (byId(d.streets.segments, "s3_forum_n").portico = 3.5), "vehicles: s3_forum_n carriageway 1 cells"); // prettier-ignore
  const bad = fresh();
  byId(bad.streets.segments, "s3_forum_s").portico = 4;
  byId(bad.streets.segments, "s3_north").portico = -1;
  const errors = validateCity(bad).errors.join(" | ");
  sure(errors.includes("(s3_forum_s).portico: two porticoes of 4 leave no carriageway in a width of 8"), errors);
  sure(errors.includes("(s3_north).portico: wanted the depth in cells (> 0)"), errors);
});

test("city prep: the rock term, per tile and the Core, against the structural and rock targets", () => {
  const d = fresh();
  const r = checkCity(d);
  sure(r.pass, r.failures.join(" | "));
  const { rock, budget } = r.analysis;
  sure(rock.provisional && ESTIMATE.rock.provisional, "the coefficients are marked provisional");
  // the towers' shells: the Nexus's 10, the Ministry's and the Purple Salon's 7 each (M13's landmarks, 2026-11-02)
  sure(rock.total > 0 && rock.total <= 6000 && rock.structural <= 8000 && rock.structural === rock.total + rock.shellWalls + rock.towers && rock.towers === 24, JSON.stringify({ ...rock, cuts: undefined, byTile: undefined })); // prettier-ignore
  const tiles = Object.entries(rock.byTile);
  sure(tiles.length === 9 && tiles.every(([, p]) => p.rock > 0 && p.rock <= 1500 && p.structural <= 2000), JSON.stringify(rock.byTile)); // prettier-ignore
  sure(tiles.reduce((s, [, p]) => s + p.rock, 0) === rock.total, "the tiles' rock sums to the city's");
  sure(rock.core?.tile === "c1_r1" && rock.core.rock === rock.byTile.c1_r1.rock, JSON.stringify(rock.core));
  sure(Math.max(...tiles.map(([, p]) => p.rock)) === rock.core.rock, "the Core is the heaviest tile");
  // the leaves are uncalibrated: the larger of the old term (1.5 a brush besides the rock) and 2.2 a structural brush
  const { brushes, structural, leaves } = budget.total;
  sure(!ESTIMATE.leavesCalibrated && !budget.leavesCalibrated, "the leaf estimate is marked uncalibrated");
  sure(leaves === Math.round(Math.max(structural * ESTIMATE.leavesPerStructural, (brushes - structural) * ESTIMATE.leavesPerBrush)), `leaves ${leaves}`); // prettier-ignore
  sure(leaves > structural * ESTIMATE.leavesPerStructural, "today the old term is the larger");
  const calibrated = fresh();
  calibrated.engine.estimate = { leavesCalibrated: true };
  sure(analyseCity(calibrated).budget.total.leaves === Math.round(structural * ESTIMATE.leavesPerStructural), "calibrated, the structural term alone"); // prettier-ignore
  breaks("over the leaf limit", (d) => (d.engine.limits.leaves.value = 15000), `engine: leaves estimated ${leaves}, over the limit 15000`); // prettier-ignore
  sure(budget.rows.some((x) => x.limit === "rock") && budget.rows.some((x) => x.limit === "structural"), "the targets are budget rows"); // prettier-ignore
  for (const c of rock.cuts) sure(c.heights >= 2 && c.heights <= d.rules.rock.maxHeights[c.layer], `${c.tile} ${c.layer} heights ${c.heights}`); // prettier-ignore
  // more outlines, more rock: a winding alley jogs, and its corners cost a band each
  const wind = fresh();
  Object.assign(byId(wind.streets.segments, "s2_court_b"), { length: 40, winding: true });
  sure(analyseCity(wind).rock.byTile.c0_r1.rock > rock.byTile.c0_r1.rock, "a winding way carves more rock");
  // the failing copies
  const core = rock.cuts.find((c) => c.tile === "c1_r1" && c.layer === "L2");
  breaks("too many heights", (d) => (d.rules.rock.maxHeights.L2 = core.heights - 1), `rock: c1_r1 on L2 is carved at ${core.heights} distinct floor and ceiling heights (on the half-storey grid), at most ${core.heights - 1}`); // prettier-ignore
  breaks("over the rock target", (d) => (d.engine.limits.rock.value = 2000), `engine: rock estimated ${rock.total}, over the target 2000`); // prettier-ignore
  breaks("over the structural target", (d) => (d.engine.limits.structural.value = 3000), `engine: structural estimated ${rock.structural}, over the target 3000`); // prettier-ignore
  breaks("a Core too heavy in rock", (d) => (d.engine.estimate = { rock: { perCornerBand: 3 } }), "tiles: c1_r1 takes", "of the rock limit", "a tile at most 25 %"); // prettier-ignore
  // the tool's report names the Core's figure
  const out = spawnSync(process.execPath, [CHECK, SPEC, "--bands", "none"], { encoding: "utf8" });
  sure(out.status === 0 && out.stdout.includes(`the Core (c1_r1) rock ${rock.core.rock}`) && out.stdout.includes("rock (provisional coefficients)") && out.stdout.includes("UNCALIBRATED"), out.stdout); // prettier-ignore
});

test("city prep: the seam portals regenerated from the streets and the tile grid", () => {
  const d = fresh();
  const made = cityPortals(d);
  sure(JSON.stringify(made) === JSON.stringify(d.tiles.portals), `the spec's portals are the tool's: ${JSON.stringify(diffPortals(d.tiles.portals, made))}`); // prettier-ignore
  sure(JSON.stringify(cityPortals(fresh())) === JSON.stringify(made), "the same description gives the same portals");
  sure(made.filter((p) => p.segment).every((p) => p.at && /^c\d_r\d\|c\d_r\d$/.test(p.seam)), "each crossing at a point on a seam"); // prettier-ignore
  // a new street across a seam: check-city fails it, the portals follow it
  const moved = fresh();
  moved.streets.segments.push({ id: "s2_seam_test", class: "alley", from: "n2_yard", to: "n2_spire_foot", district: "d2_lantern" }); // prettier-ignore
  sure(checkCity(moved).failures.some((f) => f.includes("s2_seam_test crosses the seam c2_r1|c2_r2 at [95,80] with no portal")), checkCity(moved).failures.join(" | ")); // prettier-ignore
  const diff = diffPortals(moved.tiles.portals, cityPortals(moved));
  sure(diff.added.length === 1 && diff.added[0].id === "p_s2_seam_test" && !diff.removed.length && !diff.changed.length, JSON.stringify(diff)); // prettier-ignore
  moved.tiles.portals = cityPortals(moved);
  sure(checkCity(moved).pass, checkCity(moved).failures.join(" | "));
  // the file rewritten: only the portals change, the rest byte for byte, in its own line ends
  const stale = fresh();
  stale.tiles.portals.splice(1, 2);
  stale.tiles.portals[0].at = [0, 0];
  stale.tiles.portals.push({ id: "p_old", segment: "s2_gate", at: [1, 1], seam: "c1_r0|c1_r0" });
  const staleText = splicePortals(TEXT, stale.tiles.portals);
  sure(JSON.stringify(JSON.parse(staleText).tiles.portals) === JSON.stringify(stale.tiles.portals), "spliced in");
  sure(splicePortals(staleText, made) === TEXT, "spliced back to the spec byte for byte");
  const crlf = TEXT.replace(/\r?\n/g, "\r\n");
  sure(splicePortals(splicePortals(crlf, []), made) === crlf, "CRLF kept");
  const none = JSON.parse(TEXT);
  delete none.tiles.portals;
  const added = JSON.parse(splicePortals(JSON.stringify(none, null, 1), made));
  sure(JSON.stringify(added.tiles.portals) === JSON.stringify(made), "a missing portals key is added");
  // the tool: in step on the spec, STALE and exit 1 on a stale copy, --write fixes it
  const ok = spawnSync(process.execPath, [PORTALS, SPEC], { encoding: "utf8" });
  sure(ok.status === 0 && ok.stdout.startsWith(`IN STEP  newbyzantium: ${made.length} portals`), ok.stdout + ok.stderr);
  const file = join(tmp, "nb-stale-portals.json");
  writeFileSync(file, staleText);
  const no = spawnSync(process.execPath, [PORTALS, file], { encoding: "utf8" });
  sure(no.status === 1 && no.stdout.startsWith("STALE") && no.stdout.includes(`+ ${made[1].id}`) && no.stdout.includes("- p_old") && no.stdout.includes(`~ ${made[0].id}`), no.stdout); // prettier-ignore
  const fix = spawnSync(process.execPath, [PORTALS, file, "--write"], { encoding: "utf8" });
  sure(fix.status === 0 && readFileSync(file, "utf8") === TEXT, fix.stdout + fix.stderr);
  const usage = spawnSync(process.execPath, [PORTALS], { encoding: "utf8" });
  sure(usage.status === 2, `usage exit ${usage.status}`);
});

test("city prep: the gated upper city, every public way up under a checkpoint; the lower layers porous", () => {
  const d = fresh();
  const r = checkCity(d);
  sure(r.pass, r.failures.join(" | "));
  sure(byId(d.layers, "L3").gated === true && !byId(d.layers, "L2").gated, "L3 gated, L2 not");
  const controlled = new Set(d.checkpoints.flatMap((k) => k.controls));
  const up = d.connectors.filter((c) => c.type !== "secret" && (c.access ?? "public") === "public" && c.stops.some((s) => s.startsWith("n3_")));
  sure(up.length === 11 && up.every((c) => controlled.has(c.id)), up.map((c) => c.id).join(", "));
  sure(!controlled.has("c21_hollow_stair") && !controlled.has("c21_pump_stair"), "the ways between L1 and L2 stay open");
  // shared gates: one checkpoint over the connectors that leave one place
  sure(byId(d.checkpoints, "cp2_forum").controls.length === 3 && byId(d.checkpoints, "cp2_stacks").controls.includes("c32_arcade_stair"), "grouped gates"); // prettier-ignore
  sure(d.checkpoints.length <= d.rules.checkpoints.max, `${d.checkpoints.length} checkpoints`);
  breaks("a Forum Stair unguarded", (d) => (byId(d.checkpoints, "cp2_forum").controls = ["c32_forum_lift", "c32_forum_stair_e"]), "checkpoints: c32_forum_stair_w is a public way onto the gated layer L3 (at n3_nexus) that no checkpoint controls"); // prettier-ignore
  breaks("the Spire Lift unguarded", (d) => (d.checkpoints = d.checkpoints.filter((k) => k.id !== "cp3_spire")), "checkpoints: c32_spire_lift is a public way onto the gated layer L3 (at n3_spire)"); // prettier-ignore
  // a private (keyed) way is not public: the gate does not ask for it, and the public walk does not count it
  const keyed = fresh();
  byId(keyed.connectors, "c32_spire_lift").access = "private";
  keyed.checkpoints = keyed.checkpoints.filter((k) => k.id !== "cp3_spire");
  const kf = checkCity(keyed).failures.join(" | ");
  sure(!kf.includes("gated layer") && kf.includes("on L3 the walk to a public connector is over 20 cells from n3_spire"), kf);
  const lower = fresh();
  byId(lower.layers, "L2").gated = true;
  sure(checkCity(lower).failures.some((f) => f.includes("c21_hollow_stair is a public way onto the gated layer L2")), "a gated L2 would ask for its stairs");
  const bad = fresh();
  byId(bad.layers, "L3").gated = "yes";
  sure(validateCity(bad).errors.some((e) => e.includes("layers[2] (L3).gated: wanted true")), validateCity(bad).errors.join(" | "));
});

test("city prep: placement on the plan, buildings in their districts, off the ways, doors on their streets", () => {
  const d = fresh();
  const r = checkCity(d);
  sure(r.pass && !r.failures.some((f) => f.startsWith("placement")), r.failures.join(" | "));
  const move = (id, at, footprint) => (d) => Object.assign(byId(d.buildings, id), { at, ...(footprint ? { footprint } : {}) });
  breaks("a building outside its district", move("palace_townhouses", [48, 92]), "placement: palace_townhouses reaches 8.3 cells outside its district d3_palace"); // prettier-ignore
  breaks("a building in a way", move("msr_barracks", [69, 36]), "placement: msr_barracks stands", "into avenue s3_helix");
  breaks("a building in a plaza and on the gate", (d) => Object.assign(byId(d.buildings, "gate_garage"), { at: [68, 7], footprint: [6, 8], frontage: "s2_gate_ramp" }), "placement: gate_garage stands 2 cells into plaza n2_gate_sq", "placement: gate_garage stands 1 cells into gate n2_gate"); // prettier-ignore
  breaks("a door off its street", move("drains_pawn", [46, 58], [3, 4]), "placement: drains_pawn's door is 3.1 cells from its frontage s1_drains_b, at most 1"); // prettier-ignore
  breaks("two buildings on one spot", (d) => (byId(d.buildings, "drains_den").at = byId(d.buildings, "drains_house").at), "placement: drains_den and drains_house overlap by"); // prettier-ignore
  breaks("a road inside a canal", (d) => d.streets.segments.push({ id: "s1_canal_test", class: "canal", from: "n1_bend", to: "n1_canal_n", district: "d1_canal" }), "placement: ways s1_road_c (street) and s1_canal_test (canal) overlap by 6 cells away from their shared nodes n1_bend, n1_canal_n"); // prettier-ignore
  breaks("two ways crossing with no node", (d) => d.streets.segments.push({ id: "s2_cross_test", class: "street", from: "n2_stacks_court", to: "n2_bazaar_s", district: "d2_stacks" }), "placement: ways s2_stacks (street) and s2_cross_test (street) overlap"); // prettier-ignore
  breaks("a looser door rule tightened", (d) => (d.rules.placement = { maxDoorGap: 0.1 }), "cells from its frontage", "at most 0.1");
  // a building is one tile's by its real footprint: a wide, shallow one beside a seam is not on it
  const b = byId(d.buildings, "msr_barracks");
  sure(b.footprint[1] < b.footprint[0] && Math.abs(b.at[1] - b.footprint[1] / 2 - 40) < 1e-9, `${b.at} ${b.footprint}`);
});

test("city prep: stairs no steeper than the architecture rulebook's pitch", () => {
  const pitch = JSON.parse(readFileSync(join(HERE, "../levels/rules/architecture.json"), "utf8")).dimensions.stairs.maxPitch;
  sure(pitch === 0.75 && CONNECTOR_TYPES.stair.maxGrade <= pitch && CONNECTOR_TYPES["grand-stair"].maxGrade <= pitch, `pitch ${pitch}`); // prettier-ignore
  sure(byId(fresh().connectors, "c_spine_stair").length >= 16, "the spine stair's run for its 12 cells of rise");
  breaks("the spine stair at grade 1", (d) => (byId(d.connectors, "c_spine_stair").length = 12), "connectors: c_spine_stair climbs 12 cells through its 3 stops in 12 (grade 1), a stair at most 0.75"); // prettier-ignore
  breaks("a stair at grade 0.83", (d) => (byId(d.connectors, "c21_bazaar_steps").length = 6), "connectors: c21_bazaar_steps climbs 5 cells in 6 (grade 0.83), a stair at most 0.75"); // prettier-ignore
});
